const keywords = [
  'hilti',
  'festool',
  'milwaukee',
  'makita',
  'dewalt',
  'bosch pro'
];

return keywords.map(keyword => ({ json: { keyword } }));

// Nœud de synthèse et validation des données
const items = $input.all();
const keywords = $('Mots-clés Premium').all();
const synthese = [];

for (let i = 0; i < items.length; i++) {
  const data = items[i].json;

  // Récupérer le keyword correspondant depuis le nœud "Mots-clés Premium"
  const keyword = keywords[i] ? keywords[i].json.keyword : 'unknown';

  const html = data.html || data.body || '';
  const success = data.success !== undefined ? data.success : false;
  const cloudflareDetected = data.cloudflareDetected || false;

  // Statistiques HTML
  const htmlLength = html.length;
  const hasContent = htmlLength > 10000;

  // Détection de contenu réel
  const hasLots = html.includes('class="lot') || html.includes('result') || html.includes('<article');
  const hasKeyword = keyword ? html.toLowerCase().includes(keyword.toLowerCase()) : false;

  synthese.push({
    json: {
      keyword: keyword,
      success,
      cloudflareDetected,
      htmlLength,
      hasContent,
      hasLots,
      hasKeyword,
      status: success && !cloudflareDetected && hasContent ? '✅ OK' : '⚠️ Issue',
      html: html,  // Conserver le HTML pour le nœud suivant
      timestamp: new Date().toISOString()
    }
  });
}

return synthese;

// Code d'extraction avec DATE DE VENTE
const items = $input.all();
const allResults = [];

const MARQUES_PREMIUM = ['hilti', 'festool', 'milwaukee', 'makita', 'dewalt', 'bosch', 'metabo'];

for (let i = 0; i < items.length; i++) {
  const data = items[i].json;
  const html = data.html || '';
  const keyword = data.keyword || 'unknown';

  const isCloudflareChallenge = (
    (html.includes('cf-browser-verification') && html.includes('Checking your browser')) ||
    (html.includes('challenge-platform') && html.includes('Just a moment')) ||
    (html.includes('Cloudflare') && html.length < 5000)
  );

  if (isCloudflareChallenge) {
    allResults.push({
      json: {
        error: 'Cloudflare détecté',
        keyword,
        html_preview: html.substring(0, 500)
      }
    });
    continue;
  }

  // Extraction des produits
  const lotLinkPattern = /<a[^>]+href="([^"]*)"[^>]+id="(\d+)"/gi;
  let match;
  let lotsFound = 0;

  while ((match = lotLinkPattern.exec(html)) !== null) {
    const href = match[1];
    const lotId = match[2];

    if (!href.includes('/lot-')) continue;

    const url = href.startsWith('http') ? href : 'https://www.interencheres.com' + href;

    // Bloc étendu pour capturer le contenu complet (y compris la date dans la div "bottom")
    const blockStart = match.index;
    const blockEnd = html.indexOf('</a>', blockStart);
    if (blockEnd === -1) continue;

    // On prend un bloc plus large pour capturer la date qui est dans la div "bottom"
    const lotContent = html.substring(blockStart, blockEnd + 4);

    // Extraction titre
    const titreMatch = /<div[^>]*class="[^"]*title[^"]*text-subtitle-2[^"]*"[^>]*>\s*<div[^>]*>([^<]+)<\/div>/i.exec(lotContent);
    if (!titreMatch) continue;

    const titre = titreMatch[1].trim().replace(/…$/, '');

    // Extraction date de vente (dans la div "bottom" > "text-caption font-weight-medium" > span)
    let date_vente = null;
    const dateMatch = /<div[^>]*class="[^"]*bottom[^"]*"[^>]*>[\s\S]*?<span[^>]*>(\d{2}\/\d{2}\/\d{4})<\/span>/i.exec(lotContent);
    if (dateMatch) {
      date_vente = dateMatch[1];
    }

    // Extraction estimation
    let estimation_vendeur_min = null;
    let estimation_vendeur_max = null;
    const estimationMatch = /Estimation\s*:\s*<\/span>\s*<span[^>]*>(\d+)(?:&nbsp;|\s)*€\s*-\s*(\d+)(?:&nbsp;|\s)*€/i.exec(lotContent);
    if (estimationMatch) {
      estimation_vendeur_min = parseInt(estimationMatch[1]);
      estimation_vendeur_max = parseInt(estimationMatch[2]);
    }

    // Extraction prix
    let prix = 0;
    const miseAPrixMatch = /Mise\s+à\s+prix\s*:\s*<\/span>\s*<span[^>]*>(\d+)(?:&nbsp;|\s)*€/i.exec(lotContent);
    const enchereMatch = /Enchère\s+en\s+cours\s*<\/span>\s*:\s*<span[^>]*>(\d+)(?:&nbsp;|\s)*€/i.exec(lotContent);

    if (enchereMatch) {
      prix = parseInt(enchereMatch[1]);
    } else if (miseAPrixMatch) {
      prix = parseInt(miseAPrixMatch[1]);
    } else if (estimation_vendeur_min) {
      prix = estimation_vendeur_min;
    }

    // Détection marque
    let marque_detectee = null;
    const titreLower = titre.toLowerCase();
    for (const marque of MARQUES_PREMIUM) {
      if (titreLower.includes(marque)) {
        marque_detectee = marque;
        break;
      }
    }

    allResults.push({
      json: {
        titre,
        prix,
        estimation_vendeur_min,
        estimation_vendeur_max,
        url,
        lot_id: lotId,
        keyword,
        marque_detectee,
        date_vente,
        date_detection: new Date().toISOString()
      }
    });
    lotsFound++;
  }

  console.log(`${lotsFound > 0 ? '✅' : '❌'} ${lotsFound} lots extraits pour "${keyword}" (dates: ${allResults.filter(r => r.json.date_vente).length})`);
}

return allResults.length > 0 ? allResults : [{ json: { message: 'Aucun lot extrait' } }];

// Compter les lot_id avant et après sauvegarde (approche simplifiée)
const itemsAvant = $('📖 Lire Sheet Existant').all();
const itemsApres = $input.all(); // Vient de "Sauvegarder dans Google Sheets"

const countAvant = itemsAvant.length;
const countApres = itemsApres.length;
const nouveauxProduits = countApres - countAvant;

// Logs de debug
console.log('=== DÉTECTION NOUVEAUX PRODUITS ===');
console.log('Lot IDs AVANT sauvegarde:', countAvant);
console.log('Lot IDs APRÈS sauvegarde:', countApres);
console.log('Nouveaux produits détectés:', nouveauxProduits);

// Calculer stats sur TOUS les produits (simplifié)
const marques = {};
let prixTotal = 0;
let prixCount = 0;
let prixMin = Infinity;
let prixMax = 0;
const keywordsSet = new Set();

for (const item of itemsApres) {
  const data = item.json;

  // Compter les marques
  if (data.marque_detectee) {
    marques[data.marque_detectee] = (marques[data.marque_detectee] || 0) + 1;
  }

  // Calculer stats de prix
  if (data.prix && data.prix > 0) {
    prixTotal += data.prix;
    prixCount++;
    prixMin = Math.min(prixMin, data.prix);
    prixMax = Math.max(prixMax, data.prix);
  }

  // Collecter keywords
  if (data.keyword) {
    keywordsSet.add(data.keyword);
  }
}

const prix_moyen = prixCount > 0 ? Math.round(prixTotal / prixCount) : 0;

return [{
  json: {
    total_produits: countApres,
    nouveaux_produits: nouveauxProduits,
    produits_existants: countAvant,
    marques: marques,
    prix_moyen: prix_moyen,
    prix_min: prixMin === Infinity ? 0 : prixMin,
    prix_max: prixMax,
    keywords_scanned: Array.from(keywordsSet),
    timestamp: new Date().toISOString(),
    google_sheet_url: 'https://docs.google.com/spreadsheets/d/1aXhXYEybgfXURg2QYduYL61dSPv4WPPqzp4hfgPpGNo/edit#gid=0'
  }
}];

